#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>
int main() {
  int listenfd = socket(AF_INET, SOCK_STREAM, 0);
  // ... socket setup ...
  int connfd = accept(listenfd, (struct sockaddr *) NULL, NULL);
  if (connfd < 0) {
    perror("accept");
    exit(1);
  }
  // ... handle connection on connfd ...
  close(connfd);
  close(listenfd);
  return 0;
}
